{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Artemisinin and its derivatives are reported to have low oral bioavailability by the oral route; artemisinin is the closest structural analogue (Morgan 0.1867) sharing a polycyclic lactone framework, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Artemisinin has poor oral bioavailability after oral administration due to limited solubility in water or oils; the query is even more polar (logD -1.37, TPSA 148.8), so poor absorption is expected.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Artemisinin is reported to have good absolute bioavailability after a single oral dose; if transferred, this would support high F, but it is a qualitative minority report and the query is more polar.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Artesunate, an artemisinin derivative, has an absolute bioavailability of 61% in Thai patients; however, the query lacks the artemisinin pharmacophore and is much more polar, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Idarubicin has a median absolute bioavailability of 29% (range 12-49%) in patients; although structurally distant, it demonstrates that some polar natural products can exceed 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low. The query is a highly polar, poorly permeable polycyclic lactone (logD -1.37, TPSA 148.8, 10 HBA). The closest analogue artemisinin has conflicting reports, but its qualitative low-absorption evidence and the query's even greater polarity support F<20%. High-F evidence comes from structurally distant chemotypes and is not transferable.",
  "evidence_gaps": [
    "No close analogue (Morgan >0.5) with measured absolute oral bioavailability.",
    "Artemisinin absolute F is not consistently quantified; reports range from 'good' to 'low' without a clear threshold-relevant value.",
    "No data on active uptake/efflux transporters for this specific polycyclic lactone scaffold.",
    "The effect of the tert-butyl and multiple lactone groups on permeability is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

